vector<int> topoSort(int V, vector<vector<int>>& adj) {
    vector<int> indegree(V, 0);
    for(int i=0; i<V; i++) for(int it : adj[i]) indegree[it]++;
    queue<int> q;
    for(int i=0; i<V; i++) if(indegree[i] == 0) q.push(i);
    vector<int> topo;
    while(!q.empty()) {
        int node = q.front(); q.pop();
        topo.push_back(node);
        for(int it : adj[node]) if(--indegree[it] == 0) q.push(it);
    }
    return topo;
}

bool isCycleUtil(int node, int parent, vector<vector<int>>& adj, vector<bool>& vis) {
    vis[node] = true;
    for(int adjNode: adj[node]) {
        if(!vis[adjNode]) {
            if(isCycleUtil(adjNode, node, adj, vis)) return true;
        } else if(adjNode != parent) return true;
    }
    return false;
}

vector<int> dijkstra(int V, vector<vector<pair<int, int>>>& adj, int S) {
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    vector<int> dist(V, 1e9);
    dist[S] = 0; pq.push({0, S});
    while(!pq.empty()) {
        int dis = pq.top().first, node = pq.top().second;
        pq.pop();
        for(auto it : adj[node]) {
            int adjNode = it.first, edgeWeight = it.second;
            if(dis + edgeWeight < dist[adjNode]) {
                dist[adjNode] = dis + edgeWeight;
                pq.push({dist[adjNode], adjNode});
            }
        }
    }
    return dist;
}

vector<int> bellman_ford(int V, vector<vector<int>>& edges, int S) {
    vector<int> dist(V, 1e8);
    dist[S] = 0;
    for(int i = 0; i < V - 1; i++) {
        for(auto it : edges) {
            int u = it[0], v = it[1], wt = it[2];
            if(dist[u] != 1e8 && dist[u] + wt < dist[v]) {
                dist[v] = dist[u] + wt;
            }
        }
    }
    for(auto it : edges) {
        if(dist[it[0]] != 1e8 && dist[it[0]] + it[2] < dist[it[1]]) return {-1}; // Cycle
    }
    return dist;
}

void shortest_distance(vector<vector<int>>& matrix) {
    int n = matrix.size();
    for(int k=0; k<n; k++) {
        for(int i=0; i<n; i++) {
            for(int j=0; j<n; j++) {
                if(matrix[i][k] == 1e9 || matrix[k][j] == 1e9) continue;
                matrix[i][j] = min(matrix[i][j], matrix[i][k] + matrix[k][j]);
            }
        }
    }
}

int spanningTree(int V, vector<vector<int>> adj[]) {
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    vector<int> vis(V, 0);
    pq.push({0, 0});
    int sum = 0;
    while(!pq.empty()) {
        auto it = pq.top(); pq.pop();
        int node = it.second, wt = it.first;
        if(vis[node]) continue;
        vis[node] = 1;
        sum += wt;
        for(auto it : adj[node]) {
            int adjNode = it[0], edW = it[1];
            if(!vis[adjNode]) pq.push({edW, adjNode});
        }
    }
    return sum;
}

// Requires DisjointSet class implementation.
int spanningTree(int V, vector<vector<int>>& edges) {
    sort(edges.begin(), edges.end(), [](auto& a, auto& b) { return a[2] < b[2]; });
    DisjointSet ds(V);
    int mstWt = 0;
    for(auto it : edges) {
        if(ds.findUPar(it[0]) != ds.findUPar(it[1])) {
            mstWt += it[2];
            ds.unionBySize(it[0], it[1]);
        }
    }
    return mstWt;
}

class DisjointSet {
    vector<int> parent, size;
public:
    DisjointSet(int n) {
        parent.resize(n + 1); size.resize(n + 1, 1);
        for(int i = 0; i <= n; i++) parent[i] = i;
    }
    int find(int node) {
        if(node == parent[node]) return node;
        return parent[node] = find(parent[node]); // Path compression
    }
    void unionBySize(int u, int v) {
        int rootU = find(u), rootV = find(v);
        if(rootU == rootV) return;
        if(size[rootU] < size[rootV]) {
            parent[rootU] = rootV;
            size[rootV] += size[rootU];
        } else {
            parent[rootV] = rootU;
            size[rootU] += size[rootV];
        }
    }
};
